/* Hide all gallery items except the first one on mobile devices */
@media (max-width: 767px) {
  /* Hide the entire gallery section on mobile */
  #metal-shop-gallery {
    display: none !important;
  }
}

/* For tablets, show only first image */
@media (min-width: 768px) and (max-width: 991px) {
  #metal-shop-gallery .filtr-item:not(:first-child) {
    display: none !important;
  }

  #metal-shop-gallery .filtr-item:first-child {
    max-width: 100%;
    flex: 0 0 100%;
  }

  #metal-shop-gallery {
    padding: 40px 0 !important;
  }
}
